$s='(y + 1)'; $t=$null;$e=$null; $ast=[System.Management.Automation.Language.Parser]::ParseInput($s,[ref]$t,[ref]$e); $stmt=$ast.EndBlock.Statements[0]; $cmdExpr=$stmt.PipelineElements[0]; $paren=$cmdExpr.Expression; Write-Host "Paren Type:"$paren.GetType().Name; $inner=$paren.ChildNodes[0]; Write-Host "Inner Type:"$inner.GetType().Name; if ($inner -is [System.Management.Automation.Language.BinaryExpressionAst]) { Write-Host "Left Type:"$inner.Left.GetType().Name; Write-Host "Left Text:"$inner.Left.Extent.Text; Write-Host "Right Type:"$inner.Right.GetType().Name; Write-Host "Right Text:"$inner.Right.Extent.Text }
